-- Reproducible schema-only baseline for isolated Renzo Hub staging; no user rows copied.
create table public.profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.skin_notes (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, note_date date not null, note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,note_date));
create index idx_skin_notes_user_date on public.skin_notes(user_id,note_date);
create table public.skin_routine_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, routine_date date not null, session text not null check(session in('am','pm')), completed_steps jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,routine_date,session));
create index idx_skin_logs_user_date on public.skin_routine_logs(user_id,routine_date);
create table public.user_settings (user_id uuid primary key default auth.uid() references auth.users(id) on delete cascade, settings jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.gym_sessions (id uuid primary key, user_id uuid not null references auth.users(id) on delete cascade, workout_date date not null, day integer not null check(day between 0 and 4), title text not null, cardio_target text not null, started_at timestamptz not null, completed_at timestamptz, duration_minutes integer check(duration_minutes between 0 and 600), cardio_type text not null default '', cardio_minutes integer default 0 check(cardio_minutes between 0 and 300), body_weight numeric check(body_weight between 30 and 300), energy integer check(energy between 1 and 10), fatigue integer check(fatigue between 1 and 10), notes text not null default '', exercises jsonb not null check(jsonb_typeof(exercises)='array'));
create index gym_sessions_user_date on public.gym_sessions(user_id,workout_date desc);
create unique index gym_one_draft on public.gym_sessions(user_id) where completed_at is null;
create table public.gym_plans (user_id uuid primary key references auth.users(id) on delete cascade, plan jsonb not null check(jsonb_typeof(plan)='array'), updated_at timestamptz not null default now());
create table public.news_briefs (user_id uuid not null references auth.users(id), id text not null, source text not null check(source in('ChatGPT','Codex','Claude')), title text not null, brief_date date not null, content text not null, source_url text not null default '', updated_at timestamptz not null default now(), primary key(user_id,id));
create table public.system_records (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, kind text not null check(kind in('daily','body','meal','favorite','prep','inventory','shopping','price','study','skill','portfolio','transaction','subscription','debt','goal','habit','photo')), record_date date not null default current_date, data jsonb not null default '{}'::jsonb check(jsonb_typeof(data)='object'), created_at timestamptz not null default now());
create index system_records_owner_kind_date on public.system_records(user_id,kind,record_date);
create unique index system_daily_once on public.system_records(user_id,record_date) where kind='daily';
create table public.system_preferences (user_id uuid primary key references auth.users(id) on delete cascade, data jsonb not null default '{}'::jsonb);
create function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at:=now(); return new; end; $$;
create trigger set_profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at();
create trigger set_skin_notes_updated_at before update on public.skin_notes for each row execute function public.set_updated_at();
create trigger set_skin_routine_logs_updated_at before update on public.skin_routine_logs for each row execute function public.set_updated_at();
create trigger set_user_settings_updated_at before update on public.user_settings for each row execute function public.set_updated_at();
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(user_id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))) on conflict(user_id) do nothing; return new; end; $$;
revoke all on function public.handle_new_user() from public,anon,authenticated;
grant execute on function public.handle_new_user() to postgres,service_role;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security; alter table public.skin_notes enable row level security; alter table public.skin_routine_logs enable row level security; alter table public.user_settings enable row level security; alter table public.gym_sessions enable row level security; alter table public.gym_plans enable row level security; alter table public.news_briefs enable row level security; alter table public.system_records enable row level security; alter table public.system_preferences enable row level security;
create policy profiles_select_own on public.profiles for select to authenticated using((select auth.uid())=user_id);
create policy profiles_insert_own on public.profiles for insert to authenticated with check((select auth.uid())=user_id);
create policy profiles_update_own on public.profiles for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy skin_notes_all_own on public.skin_notes for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy skin_logs_all_own on public.skin_routine_logs for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy user_settings_all_own on public.user_settings for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy gym_sessions_owner on public.gym_sessions for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy gym_plans_owner on public.gym_plans for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy news_owner on public.news_briefs for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy system_records_owner on public.system_records for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy system_preferences_owner on public.system_preferences for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
revoke all on table public.profiles,public.skin_notes,public.skin_routine_logs,public.user_settings,public.gym_sessions,public.gym_plans,public.news_briefs,public.system_records,public.system_preferences from anon,public;
grant select,insert,update,delete on table public.profiles,public.skin_notes,public.skin_routine_logs,public.user_settings,public.gym_sessions,public.gym_plans,public.news_briefs,public.system_records,public.system_preferences to authenticated;
